        type: "p",
        text: "Pythonは、パイプラインでの一括抽出や自動化された品質チェックに最適です。しかし、特定の要素のプロパティセットを目で確かめたいとき、あるいはコードを書かない人にファイルを渡すときは、クリックした要素のPsetを表示してくれるビューアーのほうが早道です。両者は互いに補い合います。大量のチェックはスクリプトで行い、例外的なケースは目で確認しましょう。",
